WITH unpacked AS (SELECT id, customer_id, created_at, items, ship_to, attributes, COALESCE(ship_to.zip, 'UNKNOWN') AS zip_or_unknown, COALESCE(attributes['device'], 'direct') AS device_or_default, ship_to.country AS ship_country FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, customer_id, SIZE(COLLECT_SET(ship_country)) AS num_ship_countries, MIN(created_at) AS started_at, SIZE(COLLECT_SET(ship_country)) AS num_ship_countries_2 FROM unpacked GROUP BY DATE_TRUNC('DAY', created_at), customer_id
